"""Turn 30 Wave 5: IAP pricing, custom kit/logo import specs, DLS26 AI difficulty/handicap observations, language list."""
import json,os,datetime
ROOT='/home/user/dls26-omega'
CP=os.path.join(ROOT,'kb','claims.jsonl')
EIP=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
claims=[json.loads(l) for l in open(CP) if l.strip()]
ev=[json.loads(l) for l in open(EIP) if l.strip()]
max_c=max(int(c['claim_id'][6:]) for c in claims)
max_e=max(int(e['evidence_id'][3:]) for e in ev if e['evidence_id'].startswith('EV-'))
ts=datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')
def mk_ev(eid,origin,artifact,summary):
    eid_full=f'EV-{eid:03d}'
    ev.append({'evidence_id':eid_full,'origin_method':origin,'artifact':artifact,'captured_at':ts,'covers':[],'summary':summary,'extracted_from':origin})
    return eid_full
def mk_claim(cid,prop,tier,evr,chal=None,vol='Low',ctx='DLS26'):
    cid_full=f'CLAIM-{cid:03d}'
    c={'claim_id':cid_full,'proposition':prop,'confidence_tier':tier,'supporting_evidence':evr,'challenges':chal or [],'context_build':ctx,'last_checked_by':f'turn 30 wave 5 ({ts})','last_valid_check':ts,'last_attempt':ts,'next_due':(datetime.datetime.utcnow()+datetime.timedelta(days=30)).strftime('%Y-%m-%d'),'volatility_tier':vol,'cross_refs':[],'replacements':None,'contradicting_evidence':[]}
    claims.append(c); return cid_full
mc=max_c
def C(prop,tier,evr,chal=None,vol='Low',ctx='DLS26'):
    global mc; mc+=1; return mk_claim(mc,prop,tier,evr,chal,vol,ctx)
e288=mk_ev(max_e+1,'official-store (apps.apple.com DLS26 listing id1462911602 Jun 2026; sportsdailyinfo coin pack comparison; amargame.shop BD third-party gem/coin pricing; bluestacks free rewards guide; footballeffect economy guide; mokoweb ads)','evidence/raw/official_turn30/EV-288_iap_economy.html',"IAP from App Store: Season Pass $3.99; Bundle of Coins $1.99; Special Offer $4.99/$5.99; Stack of Coins $3.99; Bundle of Gems $1.99; Stack of Gems $7.99; Cup of Coins $6.99; Promo Pack $9.99; Locker of Gems $16.99. Third-party coin-pack reference (2025 community, possibly different pricing): Starter $0.99/1000, Small $4.99/6000, Medium $9.99/13000, Large $19.99/28000, Mega $49.99/75000, Ultimate $99.99/160000. New player starting balance ~1,200 coins + 40 gems. Ads: ~30-40 coins per ad watched (free coin video). Prize Ladder 90-day cycle using Dream League Points, awards coins/gems/Classic Players. Daily login cycle 20 days. Daily Scenarios award 50 coins/day. Starter pack with limited-offer 'slightly upgraded' special cards priced ~990 gems (community complaint of poor value). Third-party (BDT) Season Pass ~$3/260Tk or ~$5/420Tk; Premium Season Pass ~1550Tk; 90 diamonds 320Tk; 400 1300Tk; 910 2550Tk; 2700 7050Tk; 900 coins 320Tk, 1800+150 650Tk, 3150+300 1100Tk, 5000+1300 1900Tk. Languages App Store: EN/AR/NL/FR/DE/ID/IT/JA/KO/PT/RU/ZH-CN/ES/ZH-TW/TR (15 languages total, matches DLS25 press release).")
e289=mk_ev(max_e+2,'community-web-en (dls26.net import guide; bluestacks custom kits guide; dlskiturl.com; dlslogo.com; sakibpro logo guide; dlskit.net; gamedls.net; isp64.blog)','evidence/raw/community_turn30/EV-289_kits_logo.html',"Custom kit/logo import: go My Club → Customise Team → Edit Kit/Edit Logo → Custom Kit/Custom Logo → paste direct PNG URL and confirm. Format: exactly 512x512 pixels, PNG (preferred) or JPG/WebP, transparent background recommended, under 1MB, direct URL ending in .png/.jpg/.webp (not Google Drive/Dropbox — must be hotlink-enabled CDN). Multiple kit slots: Home/Away/Third/GK. Import feature requires unlocking with 150 gems one-time payment. Logo same 512x512 PNG. Kit image must conform to official UV-template (front/back/sleeves/shorts zones) or sponsor/shirt details mis-map onto sleeves/back instead of chest.")
e290=mk_ev(max_e+3,'community-web-en (r/DLS DLS26 reviews Dec 2025-Mar 2026: garbage thread, AI useless thread, gameplay horrible downgrade, gameplay review, passing review, great changes thread, community review)','evidence/raw/reddit_turn30/EV-290_ai_difficulty.html',"DLS26 AI behavior community observations: (1) Launch (Dec 2025): passing was broken (100-rated passers felt like 42-rated bronze; balls floated); subsequent patch reverted passing physics to DLS25-like ('worse' per some users). DLS26 initial passing accounted for momentum/inertia which some considered realistic. (2) 'Hard' difficulty perceived AI handicap: AI wins balls 'artificially', user's players miss simple passes, throw-ins/shot power don't match input intensity. (3) AI defenders/GKs perceived as unpredictable; Donnaumma-tier GKs underperform; defenders sometimes 'do nothing' on certain shots. (4) DLS26 launch gameplay slower than DLS25 → control/passing/tackling stats gained value vs speed spam (fitness-coach spam discouraged). (5) C-button (lofted pass/cross) was nerfed at DLS26 launch. (6) Positive changes noted: less opponent 'lag', improved tiki-taka buildup, improved dribbling, reduced match scripting. (7) Negative points: worse player switching, 'stats feel placebo', defensive AI weaker than attacking AI, GKs unpredictable. (8) Recurring complaint: AI pressing aggressively; receiving players 'stuck' leading to interceptions; AI runs curve/run away from passes; high-rated players bullied off ball by lower-rated AI; low-tackle players dispossess high-control carriers. (9) Post-patch (Dec 18): AI perceived as 'useless again' / easier to score (reverted to first DLS26 update or worse). Long shots less effective than DLS25. (10) Legendary Division AI significantly harder than lower divisions; new players in Academy/Div4 can score 8-9 goals per game with 95-rated teams while Legendary Division is tight.")
C("Official App Store IAP pricing tiers (DLS26 iOS, Jun 2026 snapshot): Season Pass $3.99; Bundle of Coins $1.99; Stack of Coins $3.99; Cup of Coins $6.99; Bundle of Gems $1.99; Stack of Gems $7.99; Locker of Gems $16.99; Promo Pack $9.99; rotating Special Offers $4.99/$5.99. Coin value scales down per coin in larger bundles (volume discount).",'High Confidence',[e288],['IAP prices rotate with offers/promotions; exact gem/coin counts per pack TBD.'],vol='Medium')
C("New player starting balance: ~1,200 coins + 40 gems (community-reported). Limitations acknowledged: one elite player can cost 10x starter coins.",'Medium Confidence',[e288],vol='Medium')
